// Turn new Shopify orders into Odoo sale orders (skip ones already in Odoo)
const synced = new Set((($('Odoo: synced orders').first().json.result) || []).map(o => o.client_order_ref));
const products = Object.fromEntries((($('Odoo: SunGuard products').first().json.result) || []).map(p => [p.default_code, p.id]));
const partner = (($('Odoo: Shopify customer').first().json.result) || [])[0];
if (!partner) throw new Error('Create a contact named "Shopify Online Customer" in Odoo first.');

const edges = $('Get Shopify orders').first().json.data?.orders?.edges || [];
const out = [];
for (const e of edges) {
  const o = e.node;
  const ref = `SHOPIFY-${o.name.replace('#', '')}`;
  if (synced.has(ref)) continue;
  const order_line = [];
  const summary = [];
  const missing = [];
  let total = 0;
  for (const le of (o.lineItems?.edges || [])) {
    const li = le.node;
    const pid = products[li.sku];
    const price = Number(li.originalUnitPriceSet?.shopMoney?.amount || 0);
    if (!pid) { missing.push(li.sku || li.title); continue; }
    order_line.push([0, 0, { product_id: pid, product_uom_qty: li.quantity, price_unit: price }]);
    summary.push(`• [${li.sku}] ${li.title} x${li.quantity}`);
    total += price * li.quantity;
  }
  if (!order_line.length) continue;
  out.push({ json: { ref, shopify_order: o.name, partner_id: partner.id, order_line,
                     summary: summary.join('\n'), total, missing: missing.join(', ') } });
}
return out;
